  stk asegs m lo sp -> SEGTOP_A <= lo -> lo + 128 <= sp -> sp < 2^64 ->
  ro_cells asegs m GOT_SSP [C8 (Z_to_bv 64 SSP_GUARD)] -> ro_cells asegs m SSP_GUARD [C8 g] -> mem_inv asegs m ->
