(* [comment removed for export] *)
Lemma open_walkB_ok : forall (sp path fd : Z) (ra gp tp t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    F fc (m : word -> option byte) (lo : Z) (g : word) junk,
  stk asegs m lo (sp + -96) -> SEGTOP_A <= lo -> lo + 128 <= sp -> sp < 2^64 -> 0 <= fd < 2^31 ->
  rw_cells asegs m (sp + -96) [CB 16 junk; C8 g; C8 s1; C8 s0; C8 ra; C8 a2; C8 a3; C8 a4; C8 a5; C8 a6; C8 a7] ->
  ro_cells asegs m SSP_GUARD [C8 g] -> mem_inv asegs m ->
  evt asegs (fun ms' => (exists (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) F' fc',
                 ms' = MS (mkR ra (Z_to_bv 64 sp) gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 fd) a1' a2' a3' a4' a5' a6' a7'
                              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F' (ret_pc ra) fc' None m (seg_rom asegs))
                 /\ stk asegs m lo sp)
    (MS (mkR (Z_to_bv 64 0xf75e4) (Z_to_bv 64 (sp + -96)) gp tp (Z_to_bv 64 path) t1 t2 (Z_to_bv 64 0) (Z_to_bv 64 SSP_GUARD)
             (Z_to_bv 64 fd) (Z_to_bv 64 path) (Z_to_bv 64 0x8000) (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0)
             (Z_to_bv 64 0) (Z_to_bv 64 56) s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
