  stk asegs m lo (sp + -96) -> SEGTOP_A <= lo -> lo + 128 <= sp -> sp < 2^64 -> 1 <= e <= 4095 ->
  rw_cells asegs m (sp + -96) [CB 16 junk; C8 g; C8 s1; C8 s0; C8 ra; C8 a2; C8 a3; C8 a4; C8 a5; C8 a6; C8 a7] ->
  ro_cells asegs m SSP_GUARD [C8 g] -> rw_cells asegs m (bv_unsigned tp + -164) [C4 errv] ->
  164 <= bv_unsigned tp -> bv_unsigned tp + -164 + 4 <= 0x66cf88 ->
  mem_inv asegs m ->
  evt asegs (fun ms' => exists (m' : word -> option byte),
